// Check if lookahead buffer is empty
if (lfs->free.off == lfs->free.size) {
    // Refill lookahead buffer
    lfs->free.off = 0;
    int err = lfs_fs_rawtraverse(lfs, lfs->free.buffer, &lfs->free.size,
            lfs->free.begin, lfs->free.end, LFS_TYPE_DIR, 0, NULL);
    if (err) {
        return err;
    }

    // Check if we found any free blocks
    if (lfs->free.size == 0) {
        return LFS_ERR_NOSPC;
    }
}

// Find next free block using wear leveling
lfs_block_t block_bits = 0;
lfs_block_t block_count = 0;
while (true) {
    // Check if we've exhausted the lookahead buffer
    if (lfs->free.off >= lfs->free.size) {
        return LFS_ERR_NOSPC;
    }

    // Get next block bits
    block_bits = ((uint32_t*)lfs->free.buffer)[lfs->free.off / 32];
    block_count = lfs_ctz(~block_bits);

    // Check if we found a free block
    if (block_count < 32) {
        break;
    }

    // Move to next block group
    lfs->free.off += 32;
}

// Calculate block address
*block = lfs->free.begin + lfs->free.off + block_count;

// Mark block as used in lookahead buffer
((uint32_t*)lfs->free.buffer)[lfs->free.off / 32] |= (1U << block_count);

// Update lookahead offset
lfs->free.off += block_count + 1;

// Update wear count for wear leveling
lfs->free.wear[*block - lfs->free.wear_begin]++;

// Check if we need to update the wear distribution
if (lfs->free.wear_size > 0 &&
        lfs->free.wear[*block - lfs->free.wear_begin] >
        lfs->free.wear_dist[lfs->free.wear_dist_len-1]) {
    // Update wear distribution
    lfs->free.wear_dist_len = 0;
    for (lfs_block_t i = 0; i < lfs->free.wear_size; i++) {
        if (lfs->free.wear[i] > lfs->free.wear_dist[lfs->free.wear_dist_len]) {
            lfs->free.wear_dist[lfs->free.wear_dist_len] = lfs->free.wear[i];
        }
    }
    lfs->free.wear_dist_len++;
}

return LFS_ERR_OK;

